content.css:
#filteredTableContainer {
  overflow: auto;
}
#filteredTable {
  border-collapse: collapse;
}
#filteredTable th,
#filteredTable td {
  padding: 4px;
  padding-left: 8px;
  padding-right: 8px;
  padding-bottom: 4px;
  border: 1px solid #c2c2c2;
  font-weight: normal;
  font-family: "Arial", Helvetica, sans-serif;
  font-size: 8px;
  text-align: left;
}
#filteredTable th {
  background-color: black;
  color: white;
  padding-right: 16px;
}
#filteredTable td {
  background-color: white;
  color: #333;
}


